public class IdempotencyFilter : IEndpointFilter
{
    private readonly IDatabase _redis;
    public IdempotencyFilter(IConnectionMultiplexer mux) => _redis = mux.GetDatabase();

    public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext ctx, EndpointFilterDelegate next)
    {
        var httpContext = ctx.HttpContext;
        if (!httpContext.Request.Headers.TryGetValue("Idempotency-Key", out var keyHeader) ||
            string.IsNullOrWhiteSpace(keyHeader))
        {
            return Results.BadRequest(new { error = "Missing required Idempotency-Key header" });
        }

        string key = $"idempotency:{keyHeader}";
        string lockKey = $"lock:{key}";
        string fingerprint = await ComputeBodyHash(httpContext.Request);

        // 1. Kiểm tra xem key đã hoàn thành chưa
        var existing = await _redis.StringGetAsync(key);
        if (!existing.IsNullOrEmpty)
        {
            var cached = JsonSerializer.Deserialize<CachedResponse>(existing!);
            if (cached!.Fingerprint != fingerprint)
            {
                return Results.Problem("Idempotency key reused with different parameters", statusCode: 422);
            }
            httpContext.Response.Headers.Append("X-Cache-Lookup", "HIT-IDEMPOTENT");
            return Results.Content(cached.Body, "application/json", statusCode: cached.StatusCode);
        }

        // 2. Thử lấy lock phân tán trong 30 giây (tránh race condition song song)
        bool lockAcquired = await _redis.StringSetAsync(lockKey, "locked", TimeSpan.FromSeconds(30), When.NotExists);
        if (!lockAcquired)
        {
            return Results.Problem("A request with this idempotency key is currently being processed", statusCode: 409);
        }

        try
        {
            // Thực thi nghiệp vụ thanh toán gốc
            var result = await next(ctx);

            // Lưu kết quả vào Redis 24 giờ
            var toCache = new CachedResponse { Fingerprint = fingerprint, StatusCode = 200, Body = JsonSerializer.Serialize(result) };
            await _redis.StringSetAsync(key, JsonSerializer.Serialize(toCache), TimeSpan.FromHours(24));

            return result;
        }
        finally
        {
            await _redis.KeyDeleteAsync(lockKey);
        }
    }
}

