public async Task<IActionResult> HandleStripeWebhook()
{
    var json = await new StreamReader(HttpContext.Request.Body).ReadToEndAsync();
    var stripeEvent = EventUtility.ConstructEvent(json, Request.Headers["Stripe-Signature"], _webhookSecret);

    // 1. Kiểm tra xem event này đã xử lý chưa
    bool alreadyProcessed = await _db.ConsumedWebhooks.AnyAsync(w => w.EventId == stripeEvent.Id);
    if (alreadyProcessed)
    {
        // Trả về 200 OK ngay lập tức để Stripe dừng gửi lại
        return Ok(new { message = "Event already acknowledged" });
    }

    // 2. Xử lý sự kiện và lưu eventId trong cùng 1 Database Transaction
    using var tx = await _db.Database.BeginTransactionAsync();
    if (stripeEvent.Type == Events.PaymentIntentSucceeded)
    {
        var paymentIntent = stripeEvent.Data.Object as PaymentIntent;
        await FulfillOrderAsync(paymentIntent!.Metadata["order_id"]);
    }

    _db.ConsumedWebhooks.Add(new ConsumedWebhook { EventId = stripeEvent.Id, HandledAt = DateTime.UtcNow });
    await _db.SaveChangesAsync();
    await tx.CommitAsync();

    return Ok();
}

