public class PowerOfTwoChoicesLoadBalancer
{
    private readonly List<ServerNode> _nodes;
    private readonly Random _rand = new();

    public PowerOfTwoChoicesLoadBalancer(List<ServerNode> nodes)
    {
        _nodes = nodes;
    }

    public ServerNode PickNextNode()
    {
        if (_nodes.Count == 0) throw new InvalidOperationException("Không có node khả dụng");
        if (_nodes.Count == 1) return _nodes[0];

        // Bốc ngẫu nhiên 2 node bất kỳ
        int idx1 = _rand.Next(_nodes.Count);
        int idx2 = _rand.Next(_nodes.Count - 1);
        if (idx2 >= idx1) idx2++; // Đảm bảo idx2 khác idx1

        var nodeA = _nodes[idx1];
        var nodeB = _nodes[idx2];

        // Chọn node có số lượng request đang hoạt động (ActiveRequests) ít hơn
        return nodeA.ActiveRequests <= nodeB.ActiveRequests ? nodeA : nodeB;
    }
}

